@Component("beneficiary-entity-projector")
public class BeneficiaryEntityProjector implements EntityProjector<Beneficiary>{
		
	// core constructor
	public BeneficiaryEntityProjector(ProjectorRegistry registry,
										BeneficiaryRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Beneficiary> getEntityClass() {
		return Beneficiary.class;
	}

    /*
	 * Insert a Beneficiary
	 * 
     * @param	entity Beneficiary
     */
    public Beneficiary create( Beneficiary entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Beneficiary
	 * 
     * @param	entity Beneficiary
     */
    public Beneficiary update( Beneficiary entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Beneficiary
	 * 
     * @param	id		UUID
     */
    public Beneficiary delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Beneficiary entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Client
     * 
     * @param	parentId	UUID
     * @param	assignment 	Client 
     * @return	Beneficiary
     */
    public Beneficiary assignClient( UUID parentId, Client assignment ) {
	    LOGGER.info("assigning Client as " + assignment.toString() );

	    Beneficiary parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Client.class, assignment.getClientId());

	    // ------------------------------------------
		// assign the Client to the parent entity
		// ------------------------------------------ 
	    parentEntity.setClient( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Client
	 * 
	 * @param	parentId		UUID
	 * @return	Beneficiary
	 */
	public Beneficiary unAssignClient( UUID parentId ) {
		Beneficiary parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Client on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Client on the parent entithy
		// ------------------------------------------     
	    parentEntity.setClient(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Accounts
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Beneficiary
     */
    public Beneficiary addToAccounts( UUID parentId, Account addTo ) {
	    LOGGER.info("handling AssignAccountsToBeneficiaryEvent - " );
	    
	    Beneficiary parentEntity = repository.findById(parentId).get();
	    Account child = registry.project( Account.class, addTo.getAccountId());
	    
	    parentEntity.getAccounts().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Accounts
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Beneficiary
     */
	public Beneficiary removeFromAccounts( UUID parentId, Account removeFrom ) {
	    LOGGER.info("handling RemoveAccountsFromBeneficiaryEvent " );
	
	    Beneficiary parentEntity = repository.findById(parentId).get();
	    Account child = registry.project( Account.class, removeFrom.getAccountId());
	    
	    parentEntity.getAccounts().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Beneficiary via an FindBeneficiaryQuery
     * @return 	query	FindBeneficiaryQuery
     */
    @SuppressWarnings("unused")
    public Beneficiary find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Beneficiary - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Beneficiarys
     *
     * @param	query	FindAllBeneficiaryQuery 
     * @return 	List<Beneficiary> 
     */
    @SuppressWarnings("unused")
    public List<Beneficiary> findAll( FindAllBeneficiaryQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Beneficiary - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final BeneficiaryRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(BeneficiaryEntityProjector.class.getName());

}
